# inventory and orders, both on the app node, both run from the virtualenv the build Job made. Zero-code OpenTelemetry:
# opentelemetry-instrument starts each service, and the app code has no tracing in it. Both send traces and metrics to
# the gateway Collector, which forwards them to the Splunk OTel Collector agent on its node. OTEL_SEMCONV_STABILITY_OPT_IN
# is http/dup, so every HTTP span carries both the current attribute names (url.query, url.full) and the older ones
# (http.target, http.url), as during a semantic-convention migration. The kubelet checks /healthz every 2 s (readiness)
# and every 10 s (liveness) on each service, and each check is a request the services trace.
apiVersion: apps/v1
kind: Deployment
metadata:
  name: inventory
  namespace: demo
spec:
  replicas: 1
  selector:
    matchLabels: { app: inventory }
  template:
    metadata:
      labels: { app: inventory }
    spec:
      nodeName: APP_NODE
      enableServiceLinks: false
      volumes:
        - name: lab
          hostPath: { path: /opt/lab }
      containers:
        - name: app
          image: python:3.12-slim
          command: ["/lab/venv/bin/opentelemetry-instrument", "/lab/venv/bin/python", "/lab/app/inventory.py"]
          env:
            - name: POD_NAME
              valueFrom:
                fieldRef: { fieldPath: metadata.name }
            - name: POD_IP
              valueFrom:
                fieldRef: { fieldPath: status.podIP }
            - { name: OTEL_SERVICE_NAME, value: inventory }
            - { name: OTEL_EXPORTER_OTLP_ENDPOINT, value: "http://gateway:4318" }
            - { name: OTEL_EXPORTER_OTLP_PROTOCOL, value: http/protobuf }
            - { name: OTEL_RESOURCE_ATTRIBUTES, value: "deployment.environment=LAB_ENV,deployment.environment.name=LAB_ENV,k8s.pod.name=$(POD_NAME),k8s.pod.ip=$(POD_IP)" }
            - { name: OTEL_METRICS_EXPORTER, value: otlp }
            - { name: OTEL_METRIC_EXPORT_INTERVAL, value: "10000" }
            - { name: OTEL_SEMCONV_STABILITY_OPT_IN, value: http/dup }
            - { name: OTEL_LOGS_EXPORTER, value: none }
            - { name: PYTHONUNBUFFERED, value: "1" }
            - { name: WORK_MS, value: "20" }
          ports:
            - containerPort: 8081
          volumeMounts:
            - { name: lab, mountPath: /lab, readOnly: true }
          resources:
            requests: { cpu: 100m, memory: 256Mi }
            limits: { memory: 768Mi }
          readinessProbe:
            httpGet: { path: /healthz, port: 8081 }
            periodSeconds: 2
            failureThreshold: 60
          livenessProbe:
            httpGet: { path: /healthz, port: 8081 }
            periodSeconds: 10
            initialDelaySeconds: 30
            failureThreshold: 6
---
apiVersion: v1
kind: Service
metadata:
  name: inventory
  namespace: demo
spec:
  selector: { app: inventory }
  ports:
    - port: 8081
---
apiVersion: apps/v1
kind: Deployment
metadata:
  name: orders
  namespace: demo
spec:
  replicas: 1
  selector:
    matchLabels: { app: orders }
  template:
    metadata:
      labels: { app: orders }
    spec:
      nodeName: APP_NODE
      enableServiceLinks: false
      volumes:
        - name: lab
          hostPath: { path: /opt/lab }
      containers:
        - name: app
          image: python:3.12-slim
          command: ["/lab/venv/bin/opentelemetry-instrument", "/lab/venv/bin/python", "/lab/app/orders.py"]
          env:
            - name: POD_NAME
              valueFrom:
                fieldRef: { fieldPath: metadata.name }
            - name: POD_IP
              valueFrom:
                fieldRef: { fieldPath: status.podIP }
            - { name: OTEL_SERVICE_NAME, value: orders }
            - { name: OTEL_EXPORTER_OTLP_ENDPOINT, value: "http://gateway:4318" }
            - { name: OTEL_EXPORTER_OTLP_PROTOCOL, value: http/protobuf }
            - { name: OTEL_RESOURCE_ATTRIBUTES, value: "deployment.environment=LAB_ENV,deployment.environment.name=LAB_ENV,k8s.pod.name=$(POD_NAME),k8s.pod.ip=$(POD_IP)" }
            - { name: OTEL_METRICS_EXPORTER, value: otlp }
            - { name: OTEL_METRIC_EXPORT_INTERVAL, value: "10000" }
            - { name: OTEL_SEMCONV_STABILITY_OPT_IN, value: http/dup }
            - { name: OTEL_LOGS_EXPORTER, value: none }
            - { name: PYTHONUNBUFFERED, value: "1" }
            - { name: INVENTORY_URL, value: "http://inventory:8081" }
          ports:
            - containerPort: 8080
          volumeMounts:
            - { name: lab, mountPath: /lab, readOnly: true }
          resources:
            requests: { cpu: 100m, memory: 256Mi }
            limits: { memory: 768Mi }
          readinessProbe:
            httpGet: { path: /healthz, port: 8080 }
            periodSeconds: 2
            failureThreshold: 60
          livenessProbe:
            httpGet: { path: /healthz, port: 8080 }
            periodSeconds: 10
            initialDelaySeconds: 30
            failureThreshold: 6
---
apiVersion: v1
kind: Service
metadata:
  name: orders
  namespace: demo
spec:
  selector: { app: orders }
  ports:
    - port: 8080

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.80"
    }
  }
}

locals {
  k8s_version = "1.34"
  node_count  = 2
}

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_ssm_parameter" "ami" {
  name = "/aws/service/eks/optimized-ami/${local.k8s_version}/amazon-linux-2023/x86_64/standard/recommended/image_id"
}

# ---------------- network (public subnets only, no NAT) ----------------
resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true
  tags                 = { Name = "${var.lab_name}-vpc" }
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id
  tags   = { Name = "${var.lab_name}-igw" }
}

resource "aws_subnet" "public" {
  count                   = 2
  vpc_id                  = aws_vpc.main.id
  cidr_block              = cidrsubnet(aws_vpc.main.cidr_block, 8, count.index)
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  map_public_ip_on_launch = true
  tags                    = { Name = "${var.lab_name}-public-${count.index}" }
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id
  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }
  tags = { Name = "${var.lab_name}-public" }
}

resource "aws_route_table_association" "public" {
  count          = 2
  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

# ---------------- IAM ----------------
resource "aws_iam_role" "cluster" {
  name                 = "hero-lab-${var.lab_name}-cluster"
  permissions_boundary = var.permissions_boundary
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect    = "Allow"
      Action    = "sts:AssumeRole"
      Principal = { Service = "eks.amazonaws.com" }
    }]
  })
}

resource "aws_iam_role_policy_attachment" "cluster" {
  role       = aws_iam_role.cluster.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonEKSClusterPolicy"
}

resource "aws_iam_role" "node" {
  name                 = "hero-lab-${var.lab_name}-node"
  permissions_boundary = var.permissions_boundary
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect    = "Allow"
      Action    = "sts:AssumeRole"
      Principal = { Service = "ec2.amazonaws.com" }
    }]
  })
}

resource "aws_iam_role_policy_attachment" "node" {
  for_each = toset([
    "arn:aws:iam::aws:policy/AmazonEKSWorkerNodePolicy",
    "arn:aws:iam::aws:policy/AmazonEC2ContainerRegistryReadOnly",
    "arn:aws:iam::aws:policy/AmazonEKS_CNI_Policy",
  ])
  role       = aws_iam_role.node.name
  policy_arn = each.value
}

# The pipeline role only allows IAM resources named hero-lab-*, so the instance profile carries that prefix too.
resource "aws_iam_instance_profile" "node" {
  name = "hero-lab-${var.lab_name}-node"
  role = aws_iam_role.node.name
}

# ---------------- EKS control plane ----------------
resource "aws_eks_cluster" "main" {
  name     = var.lab_name
  role_arn = aws_iam_role.cluster.arn
  version  = local.k8s_version

  vpc_config {
    subnet_ids              = aws_subnet.public[*].id
    endpoint_public_access  = true
    endpoint_private_access = false
  }

  access_config {
    authentication_mode                         = "API"
    bootstrap_cluster_creator_admin_permissions = true
  }

  depends_on = [aws_iam_role_policy_attachment.cluster]
}

resource "aws_eks_access_entry" "node" {
  cluster_name  = aws_eks_cluster.main.name
  principal_arn = aws_iam_role.node.arn
  type          = "EC2_LINUX"
}

# ---------------- self-managed nodes joined with nodeadm ----------------
locals {
  user_data = <<-EOT
    MIME-Version: 1.0
    Content-Type: multipart/mixed; boundary="BOUNDARY"

    --BOUNDARY
    Content-Type: application/node.eks.aws

    ---
    apiVersion: node.eks.aws/v1alpha1
    kind: NodeConfig
    spec:
      cluster:
        name: ${aws_eks_cluster.main.name}
        apiServerEndpoint: ${aws_eks_cluster.main.endpoint}
        certificateAuthority: ${aws_eks_cluster.main.certificate_authority[0].data}
        cidr: ${aws_eks_cluster.main.kubernetes_network_config[0].service_ipv4_cidr}

    --BOUNDARY--
  EOT
}

resource "aws_instance" "node" {
  count                       = local.node_count
  ami                         = nonsensitive(data.aws_ssm_parameter.ami.value)
  instance_type               = "t3.large"
  subnet_id                   = aws_subnet.public[count.index % 2].id
  iam_instance_profile        = aws_iam_instance_profile.node.name
  vpc_security_group_ids      = [aws_eks_cluster.main.vpc_config[0].cluster_security_group_id]
  associate_public_ip_address = true
  user_data                   = local.user_data

  metadata_options {
    http_endpoint               = "enabled"
    http_tokens                 = "required"
    http_put_response_hop_limit = 2
  }

  root_block_device {
    volume_size = 30
    volume_type = "gp3"
  }

  tags = { Name = "${var.lab_name}-node-${count.index}" }

  depends_on = [aws_eks_access_entry.node, aws_iam_role_policy_attachment.node]
}

output "cluster_name" {
  value = aws_eks_cluster.main.name
}
